"use strict";
const $=id=>document.getElementById(id), csrf=document.querySelector('meta[name="csrf-token"]').content;
let cases=[], current=null, run=null, timer=null, generation=0, image=new Image(), zoom=1, pan={x:0,y:0}, drag=null, highlighted=-1;
const statuses={queued:'等待執行',running:'工具執行中',pending_data:'等待補件',pending_review:'等待人工覆核',approved:'已核准',rejected:'已退回',emergency:'急性警訊優先',blocked:'執行受阻'};
const toolNames={image_quality:'01 影像可讀性檢查',detect_candidates:'02 候選定位',check_context:'03 資料完整性確認',draft_evidence:'04 證據草稿',propose_consult:'05 會診提案',propose_followup:'06 追蹤提案'};
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,6500);}
async function api(url,options={}){const response=await fetch(url,{...options,headers:{'X-CSRF-Token':csrf,...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...options.headers}});const data=await response.json();if(!response.ok)throw Error(data.error||'請求失敗');return data;}
function context(){return {age:$('age').value===''?null:Number($('age').value),acute:$('acute').value===''?null:$('acute').value==='true',history_complete:$('history').value===''?null:$('history').value==='true',consent:$('consent').checked};}
function fillContext(c){$('age').value=c.age??'';$('acute').value=c.acute===null?'':String(c.acute);$('history').value=c.history_complete===null?'':String(c.history_complete);$('consent').checked=c.consent===true;}
async function refreshCases(){cases=await api('/api/cases');renderCases();}
function renderCases(){const list=$('caseList');list.replaceChildren();const q=$('search').value.toLowerCase();for(const c of cases.filter(c=>(c.id+' '+c.label+' '+c.modality).toLowerCase().includes(q))){const b=el('button',undefined,'case-card'+(current?.id===c.id?' selected':''));b.append(el('strong',c.id),el('p',c.label),el('small',`${c.modality} · ${c.slice_count} slices · ${c.synthetic?'SYNTHETIC':'RESEARCH'}`));b.onclick=()=>selectCase(c);list.append(b);}$('caseCount').textContent=cases.length;}
async function selectCase(c){clearTimeout(timer);generation++;const g=generation;current=c;run=null;highlighted=-1;image=new Image();$('showRef').checked=false;$('slice').max=c.slice_count-1;$('slice').value=Math.floor(c.slice_count/2);$('caseId').textContent=c.id;$('caseLabel').textContent=c.label;$('modality').textContent=c.modality;$('imageBadge').textContent=c.synthetic?'SYNTHETIC / WORKFLOW FIXTURE':`${c.modality} / RESEARCH IMAGE`;$('sourceInfo').textContent=c.source+'。'+c.source_detail;$('windowControls').hidden=!c.is_hu;$('mode').value=c.synthetic?'demo':'model';fillContext({age:null,acute:null,history_complete:null,consent:false});$('planner').value='rules';$('modalityNote').textContent=c.modality==='MRI'?'心臟 MRI 研究影像已載入。CT 鈣化模型不適用；可瀏覽切片與研究來源。':c.synthetic?'合成 CT 用於工具流程測試；候選不含模型信心值，所有任務均標示為示範。':c.is_hu?'DICOM 可調整窗位檢視。模型推論須另以訓練時的窗位匯出並驗證。':'CT 匯出影像：2.5D 推論需同序列的三張以上依序切片與已登錄模型。';$('modalityNote').className='notice'+(c.modality==='MRI'?' warn':'');renderRun();renderCases();resetView();loadImage();if(c.last_run_id){try{const r=await api('/api/runs/'+c.last_run_id);if(g===generation){run=r;fillContext(r.context);$('planner').value=r.settings.planner;$('mode').value=r.settings.mode;renderRun();poll();}}catch(e){toast(e.message);}}}
function loadImage(){if(!current)return;const g=generation,idx=Number($('slice').value),next=new Image();$('sliceNum').textContent=`${idx+1} / ${current.slice_count}`;next.onload=()=>{if(g===generation&&idx===Number($('slice').value)){image=next;draw();}};next.onerror=()=>toast('影像載入失敗');next.src=`/api/cases/${current.id}/slices/${idx}?center=${encodeURIComponent($('windowCenter').value)}&width=${encodeURIComponent($('windowWidth').value)}`;}
function resetView(){zoom=1;pan={x:0,y:0};draw();}
function draw(){const c=$('canvas'),rect=c.getBoundingClientRect(),dpr=window.devicePixelRatio||1;c.width=Math.max(1,Math.round(rect.width*dpr));c.height=Math.max(1,Math.round(rect.height*dpr));const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#0b151d';ctx.fillRect(0,0,rect.width,rect.height);if(!image.complete||!image.naturalWidth)return;const scale=Math.min((rect.width-30)/image.width,(rect.height-30)/image.height)*zoom;ctx.translate(rect.width/2+pan.x,rect.height/2+pan.y);ctx.scale(scale,scale);ctx.translate(-image.width/2,-image.height/2);ctx.drawImage(image,0,0);const boxes=run&&run.case_id===current.id&&run.center===Number($('slice').value)?run.vision?.candidates||[]:[];function box(b,color,label){ctx.strokeStyle=color;ctx.lineWidth=1.7/scale;ctx.strokeRect(b[0],b[1],b[2]-b[0],b[3]-b[1]);ctx.fillStyle=color;ctx.font=`${10/scale}px system-ui`;ctx.fillText(label,b[0],b[1]-4/scale);}
if($('showBoxes').checked)boxes.forEach((b,i)=>box(b.xyxy,i===highlighted?'#ffcf70':'#44e2cd',String(i+1)));if($('showRef').checked)(current.reference_boxes?.[$('slice').value]||[]).forEach(b=>box(b,'#efa35e','REF'));}
function renderRun(){const r=run;$('status').textContent=r?statuses[r.status]||r.status:'尚未執行';const busy=r&&['running','queued'].includes(r.status), pending=r?.status==='pending_data';$('runBtn').disabled=!!busy;$('runBtn').textContent=busy?'代理執行中…':pending?'補齊資料並續跑 →':'啟動影像協作代理 →';$('mode').disabled=!!pending||!!busy;$('planner').disabled=!!pending||!!busy;$('slice').disabled=!!busy;for(const id of ['age','acute','history','consent'])$(id).disabled=!!busy||!!(r&&!pending);$('reviewForm').hidden=r?.status!=='pending_review';$('newRun').hidden=!r||!!busy;$('export').hidden=!r;if(r)$('export').href=`/api/runs/${r.id}/export`;
const notice=$('runNotice');notice.hidden=!r||!['pending_data','blocked','emergency','approved','rejected'].includes(r.status);notice.className='notice'+(r?.status==='emergency'?' urgent':r?.status==='blocked'||pending?' warn':'');if(r){notice.textContent=r.status==='pending_data'?'待補欄位：'+r.missing.map(k=>({age:'年齡',acute:'急性警訊',history_complete:'病史備齊',consent:'使用許可'}[k]||k)).join('、'):r.error||r.notice||(r.status==='approved'?'人工核准完成，已建立 2 項本機任務。':r.status==='rejected'?'已退回並結束此工作：'+r.review.reason:'');}
const draft=$('draft');draft.hidden=!r?.draft;draft.replaceChildren();if(r?.draft){draft.append(el('h3',r.draft.demo?'證據草稿 · 合成示範':'證據草稿'),el('p',`病例 ${r.case_id} · 中心切片 ${r.center+1} · 候選 ${r.draft.candidate_count} 處`),el('p',r.draft.text));}
const list=$('candidates');list.replaceChildren();const cs=r?.vision?.candidates||[];if(!r?.vision)list.append(el('p','尚無候選推論結果。','muted'));else if(!cs.length)list.append(el('p','本次零候選。此結果不代表沒有鈣化，仍需人工檢視。','muted'));else cs.forEach((b,i)=>{const n=el('button',undefined,'candidate');n.append(el('span',`候選 ${String(i+1).padStart(2,'0')}`),el('small',b.xyxy.map(x=>Math.round(x)).join(', ')),el('span',b.confidence===null?'合成區域':(b.confidence*100).toFixed(1)+'%'));n.onclick=()=>{highlighted=i;$('slice').value=r.center;loadImage();};list.append(n);});$('candidateMeta').textContent=r?.vision?`${r.vision.trained?'登錄模型':'流程測試'} · 中心切片 ${r.center+1}`:'尚未執行';
const trace=$('traceList');trace.replaceChildren();for(const t of r?.tool_log||[]){const card=el('div',undefined,'trace-card');card.append(el('strong',toolNames[t.tool]),el('small',`${t.plan.source} · 規劃 ${t.plan.elapsed_ms} ms · 工具 ${t.elapsed_ms} ms`));if(t.plan.reason)card.append(el('small',t.plan.reason));const details=el('details');details.append(el('summary','執行證據'),el('pre',JSON.stringify({planning:t.plan,result:t.result},null,2)));card.append(details);trace.append(card);}if(r?.error)trace.append(el('p',r.error,'notice warn'));if(!r?.tool_log?.length)trace.append(el('p',r?.status==='emergency'?'急性警訊已優先攔截，未等待影像或 LLM。':'尚無工具紀錄。','muted'));
const taskList=$('taskList');taskList.replaceChildren();for(const t of r?.tasks||[]){const card=el('div',undefined,'task');card.append(el('strong',(t.demo?'[示範] ':'')+(t.kind==='consult'?'會診檢視':'交接追蹤')),el('p',t.description),el('p',`${t.time} · ${t.status}`));taskList.append(card);}if(!r?.tasks?.length)taskList.append(el('p','目前 0 項任務。人工核准後才建立。','muted'));$('taskCount').textContent=r?.tasks?.length||0;draw();}
async function poll(){clearTimeout(timer);if(!run||!['running','queued'].includes(run.status))return;const g=generation,id=run.id;timer=setTimeout(async()=>{try{const r=await api('/api/runs/'+id);if(g===generation&&run?.id===id){run=r;renderRun();poll();}}catch(e){toast(e.message);}},700);}
$('search').oninput=renderCases;$('slice').oninput=loadImage;$('applyWindow').onclick=loadImage;$('reset').onclick=resetView;$('zoomIn').onclick=()=>{zoom=Math.min(6,zoom*1.2);draw();};$('zoomOut').onclick=()=>{zoom=Math.max(.5,zoom/1.2);draw();};$('showBoxes').onchange=draw;$('showRef').onchange=draw;new ResizeObserver(draw).observe($('canvasWrap'));
$('canvas').onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,px:pan.x,py:pan.y};$('canvas').setPointerCapture(e.pointerId);};$('canvas').onpointermove=e=>{if(drag){pan.x=drag.px+e.clientX-drag.x;pan.y=drag.py+e.clientY-drag.y;draw();}};$('canvas').onpointerup=()=>drag=null;$('canvas').onpointercancel=()=>drag=null;$('canvas').addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.5,Math.min(6,zoom*(e.deltaY<0?1.1:.9)));draw();},{passive:false});
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));for(const id of ['prepare','trace','tasks'])$(id).hidden=id!==b.dataset.tab;});
$('contextForm').onsubmit=async e=>{e.preventDefault();if(!current)return;const g=generation;$('runBtn').disabled=true;try{const body=run?.status==='pending_data'?{context:context(),version:run.version}:{case_id:current.id,context:context(),planner:$('planner').value,mode:$('mode').value,center:Number($('slice').value)};const route=run?.status==='pending_data'?`/api/runs/${run.id}/resume`:'/api/runs';const result=await api(route,{method:'POST',body:JSON.stringify(body)});const r=await api('/api/runs/'+result.id);if(g===generation){run=r;current.last_run_id=r.id;renderRun();poll();}}catch(err){toast(err.message);renderRun();}};
async function review(decision){try{await api(`/api/runs/${run.id}/review`,{method:'POST',body:JSON.stringify({decision,reviewer:$('reviewer').value,reason:$('reason').value,version:run.version})});run=await api('/api/runs/'+run.id);renderRun();toast(decision==='approve'?'已核准，建立 2 項本機協作任務。':'已退回並保存原因。');}catch(e){toast(e.message);}}
$('reviewForm').onsubmit=e=>{e.preventDefault();review('approve');};$('reject').onclick=()=>review('reject');
$('uploadBtn').onclick=()=>$('uploadDialog').showModal();$('closeUpload').onclick=()=>$('uploadDialog').close();$('uploadFiles').onchange=()=>{$('uploadOrder').replaceChildren(...Array.from($('uploadFiles').files).map((f,i)=>el('div',`${i+1}. ${f.name}`)));};$('uploadForm').onsubmit=async e=>{e.preventDefault();try{const result=await api('/api/cases',{method:'POST',body:new FormData(e.target)});$('uploadDialog').close();await refreshCases();selectCase(cases.find(c=>c.id===result.id));toast('已匯入影像；上傳原始檔名與 DICOM 病人欄位未保存。');}catch(err){toast(err.message);}};
$('systemBtn').onclick=async()=>{$('systemDialog').showModal();$('systemDetails').textContent='檢查中…';try{const [health,lemonade]=await Promise.all([api('/api/health'),api('/api/lemonade')]);$('systemDetails').textContent=JSON.stringify({workstation:health,lemonade},null,2);}catch(e){$('systemDetails').textContent=e.message;}};$('closeSystem').onclick=()=>$('systemDialog').close();
(async()=>{try{await refreshCases();await selectCase(cases.find(c=>c.modality==='MRI')||cases[0]);const h=await api('/api/health');$('serviceHint').textContent=h.vision.configured?'CT 模型已登錄 · AMD 實機待驗收':'CT 權重尚未登錄 · MRI 檢視與合成流程可用';}catch(e){toast(e.message);}})();

$('newRun').onclick=()=>{clearTimeout(timer);run=null;fillContext({age:null,acute:null,history_complete:null,consent:false});$('mode').value=current.synthetic?'demo':'model';renderRun();};
